/* Three choices and a banker conversation, contained within the bank screen. */
for(const list of [debitAccounts,expenseAccounts])if(!list.includes('支払利息'))list.push('支払利息');
for(const k of ['短期借入金','長期借入金'])if(!creditAccounts.includes(k))creditAccounts.push(k);
descriptions.支払利息='銀行借入の利息。元金の返済と異なり、当期の費用になります。';
descriptions.短期借入金='運転資金の借入。毎月利息を支払い、３か月後に元金を一括返済。前月から書き換えを審査できます。';
descriptions.長期借入金='設備購入の借入。翌月から元金均等返済と利息の支払いが始まります。';
let bankPurpose='short',bankRequest=null,bankPlanAssumptions=null;
const detailedBank=renderBank;
// 銀行員Aはパキちゃん語：文末を「〜ゆ。」にする（です→ゆ、でしょうか→ゆ、それ以外は句点の前にゆ）。
const bankerYu=text=>String(text).split(/(<br>)/).map(seg=>seg==='<br>'?seg:seg.replace(/(?:でしょうか|ですか)？/g,'ゆ？').replace(/です([。！])/g,'ゆ$1').replace(/([^ゆ。！？\s>])([。！？])/g,'$1ゆ$2').replace(/([^ゆ。！？\s>）)])$/,'$1ゆ。')).join('');
const bankerSpeech=text=>`<div class="banker-conversation"><img src="assets/characters/wonderland-girl.png" alt="銀行員A"><div><b>銀行員A</b><p>${bankerYu(text)}</p></div></div>`;
function currentBankAssessment(){return bankAssessment(annualSeries(),state.balances);}
function bankChoices(){const a=currentBankAssessment(),q=BankLoans.quote(state,a,bankPurpose);return `<label class="bank-purpose">資金の使い道<select id="bankPurpose"><option value="startup" ${bankPurpose==='startup'?'selected':''}>創業赤字の補填（最長５年）</option><option value="short" ${bankPurpose==='short'?'selected':''}>運転資金</option>${Object.entries(E.EQUIPMENT).map(([id,s])=>`<option value="${id}" ${bankPurpose===id?'selected':''}>${s.name}の購入${state.equipment[id]?'（購入済み）':''}</option>`).join('')}</select></label><p>希望額を３案から選んで、審査を申し込みます。${q.equipment?'設備代金 '+yen(q.need)+'。借入不足分は自己資金で支払います。':(bankPurpose==='startup'?'創業赤字補填の必要額から既存残高を引いた額 ':'必要運転資金から既存の短期借入を引いた額 ')+yen(q.need)+' を基に計算。'}</p><div class="loan-options">${q.amounts.map((n,i)=>`<button data-loan-request="${n}" ${n<=0?'disabled':''}><span>${['必要額の半分','必要額どおり','審査の上限まで'][i]}</span><strong>${yen(n)}</strong><small>${['不足分は自己資金で補う','必要額の100％を相談','審査可能な上限を確認'][i]}</small></button>`).join('')}</div><p class="note">１万円単位で切り下げ。同額になる場合があります。枠や必要額が１万円未満の案は選べません。申込みだけでは預金は動きません。</p>`;}
renderBank=function(){const a=currentBankAssessment();const welcome=a.score===null?'まずは決算実績を拝見したいです。希望額のご相談はできますが、最初の３月決算までは審査保留になります。':a.grade==='A'&&a.eligible&&Math.max(a.short.available,a.equipment.available)>=10000?'財務内容が良好ですね。資金の使い道があれば、ぜひもう少しお借りいただきたいです。ご希望額を伺って、増額できる範囲をご案内します。':'ご希望額と資金の使い道を教えてください。返済力と現在の借入残高を確認します。';return `<section class="bank-desk"><h2>銀行員Aの融資相談</h2>${bankerSpeech(welcome)}<div class="bank-summary"><span>財務スコア <b>${a.score??'未確定'}${a.score===null?'':' / 100'}</b></span><span>格付け <b>${a.grade}</b></span><span>年利 <b>${a.rate===null?'審査後':a.rate.toFixed(1)+'％'}</b></span></div>${startupNotice(a)}${renewalPanel(a)}${bankChoices()}${state.closed?'<p class="note">今月の帳簿は確定済みです。相談後の融資実行は次の月にできます。</p>':''}${state.bankBorrowedTurn===state.turn?'<p>今月の融資は実行済みです。</p>':''}<details class="bank-details"><summary>融資枠・スコアの内訳を見る</summary>${detailedBank()}</details><details class="bank-details"><summary>返済中の借入を見る</summary>${loanList()}</details></section>`;};
function loanList(){return (state.loans||[]).filter(l=>l.balance>0).map(l=>`<p>${l.kind==='short'?'運転資金':l.kind==='startup'?'創業赤字補填（長期）':'設備資金'}：残高 ${yen(l.balance)} ／ 年利 ${l.rate.toFixed(1)}％ ／ ${l.kind==='short'?'TURN '+(l.due||l.start+l.months)+'に元金一括返済':'月の元金 '+yen(Math.min(l.balance,l.payment))+'、利息は残高に応じて減少'}</p>`).join('')||'<p>返済中の借入はありません。</p>';}
function equipmentCashFlowLesson(amount,d,a){
 const payment=E.gross(state,d.spec.cost),existing=E.scheduled(state,state.turn+1),newPrincipal=Math.ceil(amount/d.months),newInterest=Math.floor(amount*d.rate/1200);
 return `<section class="bank-cashflow"><h3>銀行員Aのキャッシュフロー解説</h3>${bankerSpeech('キャッシュフローは、現金が実際に入ったり出たりする流れです。設備資金を借りると預金は増えますが、売上や利益にはなりません。設備代金を支払えば、その分の預金が減ります。')}<dl class="equipment-facts"><div><dt>財務：今回の借入入金</dt><dd>＋${yen(amount)}</dd></div><div><dt>投資：設備代金の支払（税込）</dt><dd>▲${yen(payment)}</dd></div><div><dt>今回の預金の増減</dt><dd>${amount-payment>=0?'＋':'▲'}${yen(Math.abs(amount-payment))}</dd></div><div><dt>実行直後の預金</dt><dd>${yen(state.balances.預金+amount-payment)}</dd></div><div><dt>翌月の元利返済予定（既存借入含む）</dt><dd>${yen(existing.principal+existing.interest+newPrincipal+newInterest)}</dd></div></dl>${bankerSpeech('営業のキャッシュフローは、売上代金の回収から仕入・給与などの支払いを引いたお金の動きです。減価償却費は利益を減らしますが、その月に現金が出る費用ではありません。一方、借入元金の返済は費用にならなくても現金が出ていきます。')}<p>このゲームの審査の年間弁済可能額は<strong>経常利益＋減価償却費</strong>を基礎に計算。現在の審査額 ${a.capacity===null?'未確定':fmt(a.capacity||0)}。これは返済力を見る目安で、実際の営業キャッシュフローとは異なります。</p><p>売掛金・在庫の増加、納税、冬の売上減少も資金を使います。投資計画の「最低月末預金」まで確認してから契約しましょう。</p></section>`;
}
function requestBankLoan(amount){const a=currentBankAssessment(),d=BankLoans.assess(state,a,bankPurpose,amount),linkedPlan=bankPlanAssumptions&&bankPlanAssumptions.equipment===bankPurpose?structuredClone(bankPlanAssumptions):null;bankRequest=null;let body=bankerSpeech(d.reasons.join('<br>')),recheckError=false;
 if(d.status==='approved'){
 body+=`<div class="loan-terms"><p>希望額 <b>${yen(amount)}</b> ／ 年利 ${d.rate.toFixed(1)}％</p><p>${d.equipment||bankPurpose==='startup'?'返済期間 '+d.months+'か月・元金均等（毎月 '+yen(Math.ceil(amount/d.months))+'、最終回で端数調整）。'+(d.equipment?'設備購入も同時に実行します。':'赤字補填資金として会社の預金に入ります。'):'３か月後に元金 '+yen(amount)+' を一括返済。前月から書き換え相談可（再審査・自動更新なし）。'}</p><p>翌月から利息を支払います。初回利息 ${yen(Math.floor(amount*d.rate/1200))}。</p></div>`;
 if(d.equipment)body+=equipmentCashFlowLesson(amount,d,a);
 if(linkedPlan&&d.equipment&&typeof InvestmentPlanner!=='undefined'){const actualPlan={...linkedPlan,delay:0,loan:amount,rate:d.rate,term:d.months},actual=InvestmentPlanner.compare(state,actualPlan).investment,changed=linkedPlan.loan!==amount||linkedPlan.rate!==d.rate||linkedPlan.term!==d.months;recheckError=!!actual.error;const recheck=actual.error?`<p class="negative">再試算できません：${actual.error}</p>`:`<p>再試算：期間損益 <b>${fmt(actual.profit)}</b> ／ 最低月末預金 <b class="${actual.minimumCash<0?'negative':''}">${fmt(actual.minimumCash)}</b> ／ 最終預金 <b>${fmt(actual.endCash)}</b>${actual.ended?' ／ <span class="negative">途中で支払不能</span>':''}</p>`;body+=`<section class="bank-plan-recheck"><h3>審査条件で再試算</h3><p>計画時：借入 ${yen(linkedPlan.loan)}・年利 ${Number(linkedPlan.rate).toFixed(1)}％・${linkedPlan.term}か月<br>審査後：借入 ${yen(amount)}・年利 ${d.rate.toFixed(1)}％・${d.months}か月</p>${changed?'<p class="negative">条件が変わったため、古い試算のまま契約せず審査条件で計算し直しました。</p>':'<p>計画時と審査条件は一致しています。</p>'}${recheck}</section>`;}
 if(d.upsell)body+=bankerSpeech('スコアが'+a.score+'点と良好ですので、'+yen(d.upsell)+'まで増額はいかがでしょうか？必要なければ、元の希望額のままでも大丈夫です。')+`<p class="note">増額時：初回利息 ${yen(Math.floor(d.upsell*d.rate/1200))}。増額部分の年間利息目安 ${yen(Math.floor((d.upsell-amount)*d.rate/100))}（残高一定の場合）。${d.equipment?'月の元金 '+yen(Math.ceil(d.upsell/d.months)):'３か月後の元金返済 '+yen(d.upsell)}。</p>`;
 const blocked=recheckError||state.closed||state.ended||state.bankBorrowedTurn===state.turn||state.turn>=120||d.equipment&&((state.actionLocked&&!(state.actionLocked==='bank'&&state.bankConsultedTurn===state.turn))||state.equipment[bankPurpose]||d.spec.requires&&!state.equipment[d.spec.requires]);
 if(!blocked)bankRequest={purpose:bankPurpose,amount,rate:d.rate,months:d.months,turn:state.turn,entryCount:state.entries.length};
 body+=`<div class="loan-decisions"><button data-loan-confirm="${amount}" ${blocked?'disabled':''}>希望額 ${yen(amount)}で借りる</button>${d.upsell?`<button data-loan-request="${d.upsell}" ${blocked?'disabled':''}>提案額 ${yen(d.upsell)}で再審査・再試算</button>`:''}</div>${blocked?'<p>融資・設備の条件または再試算を確認してください。実行できない場合は次の月に再相談できます。</p>':''}`;
 }else if(d.status==='excess')body+=`<p>融資可能額まで減らして再申込みできます。</p><button data-loan-request="${d.limit}">上限 ${yen(d.limit)}で再審査</button>`;
 body+='<button id="declineLoan" class="loan-cancel">今回は借りない</button>';openShop({approved:'融資条件のご案内',excess:'希望額が上限を超えています',denied:'審査結果：否決',pending:'審査結果：保留',invalid:'希望額の確認'}[d.status],body);
}
function confirmBankLoan(amount){if(!bankRequest)return;const a=currentBankAssessment(),d=BankLoans.assess(state,a,bankRequest.purpose,amount);if(amount!==bankRequest.amount||state.turn!==bankRequest.turn||state.entries.length!==bankRequest.entryCount||d.status!=='approved'||d.rate!==bankRequest.rate||d.months!==bankRequest.months){requestBankLoan(amount);return;}try{state=BankLoans.execute(state,a,bankRequest.purpose,amount);bankRequest=null;bankPlanAssumptions=null;choice.action=state.actionLocked||choice.action;choice.quantities=E.recommend(state,currentAction(),choice.price,choice.payment||'cash');choice.orderSource='recommended';closeShop();closeStatements();renderPlanning();saveGame();toast('融資を実行しました。預金と借入金に反映しています。');}catch(e){openShop('融資条件の確認',bankerSpeech(e.message)+'<button id="declineLoan">戻る</button>');}}
document.addEventListener('change',e=>{if(e.target.id==='bankPurpose'){bankPurpose=e.target.value;bankRequest=null;bankPlanAssumptions=null;renderTable();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.loanRequest){requestBankLoan(Number(b.dataset.loanRequest));}else if(b.dataset.loanConfirm){confirmBankLoan(Number(b.dataset.loanConfirm));}else if(b.id==='declineLoan'){bankRequest=null;bankPlanAssumptions=null;closeShop();}else if(b.id==='bankMenu'){bankPlanAssumptions=null;openStatements();tab='bank';renderTable();}});
const bankMenu=document.createElement('button');bankMenu.id='bankMenu';bankMenu.className='help-top';bankMenu.textContent='銀行';document.querySelector('.top').append(bankMenu);

function renewalPanel(a){const loans=(state.loans||[]).map((l,i)=>({l,i})).filter(({l})=>l.kind==='short'&&l.balance>0&&(l.due||l.start+l.months)-state.turn<=1);return loans.map(({l,i})=>bankerSpeech('短期借入 '+yen(l.balance)+' の期日が近づいています。現在の財務内容で書き換えを審査できます。否決・見送りの場合は期日に元金返済が必要です。')+`<button data-renew-loan="${i}" ${state.closed?'disabled':''}>書き換えを相談する</button>`).join('');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.renewLoan!==undefined){const i=Number(b.dataset.renewLoan),l=state.loans[i];openShop('短期借入の３か月更新',bankerSpeech('同額更新は行動不要。減額更新も行動不要ですが、差額を今すぐ返済します。増額申込みは承認・否決にかかわらず今月の行動を使います。')+`<p>現在の元本 ${yen(l.balance)}。更新後の元本総額を指定してください。現状の枠を超える更新はできません。</p><label>更新後の元本（円）<input id="renewTarget" type="number" min="0" step="10000" value="${l.balance}"></label><button data-review-renew="${i}">更新内容を確認</button>`);}
 else if(b.dataset.reviewRenew!==undefined){const i=Number(b.dataset.reviewRenew),amount=Number(el('renewTarget').value),l=state.loans[i];if(!Number.isSafeInteger(amount)||amount<0){toast('０以上の整数を入力してください');return;}openShop('更新申込みの確認',`<p>${amount>l.balance?'注意：増額の再審査に今月の行動を使います。否決でも戻りません。クエは店番できず、従業員だけで営業します。':amount<l.balance?'差額 '+yen(l.balance-amount)+' を今すぐ返済します。行動消費はありません。':'同額更新です。行動消費はありません。'}</p><button data-confirm-renew="${i}" data-target="${amount}">この条件で申し込む</button>`);}
 else if(b.dataset.confirmRenew!==undefined){try{state=BankLoans.renew(state,currentBankAssessment(),Number(b.dataset.confirmRenew),Number(b.dataset.target));renderPlanning();saveGame();openShop('更新の審査結果',bankerSpeech(state.renewalDecision.reason));}catch(err){toast(err.message);}}
});

function startupNotice(a){const support=BankLoans.startupSupport(state,a,'startup');return support.startup?`<p class="note"><b>２年目・創業赤字補填の長期融資</b><br>直近２か月連続の月次CF黒字が条件。CFは経常利益＋減価償却費。上限150万円・初年度赤字額以内、最長５年。CFから既存返済を引いた余力で毎月元利返済できる額まで。${support.startupMonths.map(x=>`第${fy(x.turn)}期 ${month(x.turn)}月：${x.cashFlow===null?'未確定':fmt(x.cashFlow)}`).join(' ／ ')}<br>${support.eligible?'条件充足・年利'+support.rate.toFixed(1)+'％':'現時点では条件未達'}。設備融資は通常審査です。</p>`:'';}
